use crate::tokens::Tokens;

use iced_core::{
    Color, color,
    theme::{Base, Mode, Style},
};

const NAME: &str = "Fluent Theme";

#[derive(Clone, Debug)]
pub enum Theme {
    Light(Tokens),
    Dark(Tokens),
}

/// Defines a set of color variants derived from a brand color ramp
/// generated from a single base (brand) color and mapped
/// across different intensity levels (e.g. 10–160). These variants
/// are used throughout the design system to ensure consistent theming,
/// contrast, and visual hierarchy across components.
///
/// Color ramps can be generated by the [Fluent Theme Designer](https://storybooks.fluentui.dev/react/?path=/docs/theme-theme-designer--docs).
///
/// **⚠️ Warning:**
/// This crate performs no contrast or accessibility checks on the provided brand colors.
pub struct BrandVariants {
    pub b10: Color,
    pub b20: Color,
    pub b30: Color,
    pub b40: Color,
    pub b50: Color,
    pub b60: Color,
    pub b70: Color,
    pub b80: Color,
    pub b90: Color,
    pub b100: Color,
    pub b110: Color,
    pub b120: Color,
    pub b130: Color,
    pub b140: Color,
    pub b150: Color,
    pub b160: Color,
}

impl BrandVariants {
    pub const DEFAULT: BrandVariants = BrandVariants {
        b10: color!(0x001526),
        b20: color!(0x002848),
        b30: color!(0x043862),
        b40: color!(0x004578),
        b50: color!(0x004c87),
        b60: color!(0x005a9e),
        b70: color!(0x106ebe),
        b80: color!(0x0078d4),
        b90: color!(0x1890f1),
        b100: color!(0x2899f5),
        b110: color!(0x3aa0f3),
        b120: color!(0xffffff),
        b130: color!(0x82c7ff),
        b140: color!(0xc7e0f4),
        b150: color!(0xdeecf9),
        b160: color!(0xeff6fc),
    };
}

impl Theme {
    pub fn tokens(&self) -> &Tokens {
        match self {
            Theme::Dark(tokens) => tokens,
            Theme::Light(tokens) => tokens,
        }
    }

    pub const fn light(brand: Option<BrandVariants>) -> Self {
        Self::Light(Tokens::light(brand))
    }

    pub const fn dark(brand: Option<BrandVariants>) -> Self {
        Self::Dark(Tokens::dark(brand))
    }

    pub const fn is_light(&self) -> bool {
        matches!(self, Theme::Light(_))
    }

    pub const fn is_dark(&self) -> bool {
        matches!(self, Theme::Dark(_))
    }
}

impl std::fmt::Display for Theme {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl Base for Theme {
    fn default(preference: Mode) -> Self {
        match preference {
            Mode::None => Self::dark(None),
            Mode::Light => Self::light(None),
            Mode::Dark => Self::dark(None),
        }
    }

    fn mode(&self) -> Mode {
        match self {
            Self::Light(_) => Mode::Light,
            Self::Dark(_) => Mode::Dark,
        }
    }

    fn base(&self) -> Style {
        let tokens = self.tokens();

        Style {
            background_color: tokens.neutral_background4,
            text_color: tokens.neutral_foreground1,
        }
    }

    fn palette(&self) -> Option<iced_core::theme::Palette> {
        None
    }

    fn name(&self) -> &str {
        NAME
    }
}
